const data = $input.first().json;
const webinars = data.webinars || [];
const formData = $('Set: Format Data').first().json;
const now = new Date();

const upcoming = webinars
  .filter(w => w.start_time && new Date(w.start_time) > now)
  .sort((a, b) => new Date(a.start_time) - new Date(b.start_time));

if (!upcoming.length) {
  throw new Error('No upcoming Zoom webinar found. Check your Zoom account has a scheduled webinar.');
}

const next = upcoming[0];
const webinarDate = new Date(next.start_time);

// YYYY-MM-DD HH:mm (UK time) — kept for legacy / DB storage
const londonTimeStr = webinarDate
  .toLocaleString('sv-SE', { timeZone: 'Europe/London', hour12: false })
  .substring(0, 16);

// Reliable formatted date: "Jul 26, 2026 at 7PM UK"
// Uses Intl.DateTimeFormat — avoids locale-dependent .replace() fragility
const londonHour24 = parseInt(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'Europe/London',
    hour: '2-digit',
    hour12: false
  }).format(webinarDate),
  10
);

const isPM   = londonHour24 >= 12;
const hour12 = londonHour24 === 0 ? 12 : londonHour24 > 12 ? londonHour24 - 12 : londonHour24;
const ampm   = isPM ? 'PM' : 'AM';

const month = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/London', month: 'short'  }).format(webinarDate);
const day   = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/London', day:   'numeric' }).format(webinarDate);
const year  = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/London', year:  'numeric' }).format(webinarDate);

const webinar_formatted_date = `${month} ${day}, ${year} at ${hour12}${ampm} UK`;

return [{
  json: {
    ...formData,
    webinar_id:             String(next.id),
    webinar_name:           next.topic || '',
    webinar_date:           londonTimeStr,
    webinar_formatted_date,
    webinar_timezone:       'Europe/London',
    webinar_duration:       next.duration || 60
  }
}];

