parameters.jsCode:
const d = $('HTTP: Get Upcoming Zoom Webinars').first().json;
const webinars = d.webinars || [];
const now = new Date();

// Sort to find the true next webinar (avoids webinars[0] ordering assumption)
const upcoming = webinars
  .filter(w => w.start_time && new Date(w.start_time) > now)
  .sort((a, b) => new Date(a.start_time) - new Date(b.start_time));

if (!upcoming.length) {
  throw new Error('No upcoming webinar found for reminder calculation.');
}

const webinarDate = new Date(upcoming[0].start_time);
const h  = (webinarDate - now) / 3600000;
const ms = webinarDate.getTime();

// ISO UTC strings — unambiguous; Wait nodes fire correctly regardless of
// the n8n workflow timezone (fixes the Europe/Madrid vs Europe/London 1-hour gap)
const toISO = (date) => date.toISOString();

return [{
  json: {
    ...d,
    hoursUntil:          Math.round(h * 10) / 10,

    reminder_48h:        toISO(new Date(ms - 48 * 3600000)),
    reminder_24h:        toISO(new Date(ms - 24 * 3600000)),
    reminder_2h:         toISO(new Date(ms -  2 * 3600000)),

    reminder_5m_before:  toISO(new Date(ms -  5 * 60000)),
    reminder_exact:      toISO(new Date(ms)),

    reminder_15m_before: toISO(new Date(ms - 15 * 60000)),
    reminder_15m_after:  toISO(new Date(ms + 15 * 60000)),
    reminder_30m_after:  toISO(new Date(ms + 30 * 60000))
  }
}];

